#![forbid(unsafe_code)]
use std::{fs,path::Path,collections::BTreeSet};use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn main()->Result<(),Box<dyn std::error::Error>>{let a:Vec<_>=std::env::args().collect();if a.len()!=3{return Err("Uso: CARPETA_PAQUETES CONSTANCIA_NUEVA".into())}let mut total=0usize;let mut bytes=0usize;let mut packets=0;for e in fs::read_dir(&a[1])?{let p=e?.path();if !p.is_file()||p.extension().and_then(|s|s.to_str())!=Some("json"){continue}let v:Value=serde_json::from_slice(&fs::read(&p)?)?;let Some(rows)=v["archivos"].as_array()else{continue};let mut names=BTreeSet::new();for r in rows{let path=r["ruta"].as_str().ok_or("Ruta")?;if path.starts_with('/')||path.contains('\\')||path.split('/').any(|p|p==".."||p==".")||!names.insert(path){return Err("Ruta no restituible".into())}let b=r["contenido_utf8"].as_str().ok_or("Texto")?.as_bytes();if r["bytes"].as_u64()!=Some(b.len() as u64)||r["sha256"]!=format!("{:x}",Sha256::digest(b)){return Err("Contenido no coincide con huella original".into())}total+=1;bytes+=b.len();}packets+=1;}
if packets!=10{return Err("Inventario de paquetes incompleto".into())}let proof=json!({"conforme":true,"paquetes":packets,"originales_restituibles":total,"bytes_originales":bytes,"alcance":"Decodificación UTF-8 y cotejo de longitud/SHA-256 de todos los originales incluidos"});let out=Path::new(&a[2]);if out.exists(){return Err("Constancia existente".into())}fs::write(out,serde_json::to_vec_pretty(&proof)?)?;println!("{proof}");Ok(())}
